<?php
class HintInfo
{
    public static function RandImage()
    {
        $n = rand(1, 8);
        
        if ($n == 1)
            return "<img src='data:image/png;base64,' width='32' height='32'>";

        if ($n == 2)
            return "<img src='data:image/png;base64,' width='32' height='32'>";

        if ($n == 3)
            return "<img src='data:image/png;base64,' width='32' height='32'>";
        
        if ($n == 4)
            return "<img src='data:image/png;base64,' width='32' height='32'>";

        if ($n == 5)
            return "<img src='data:image/png;base64,' width='32' height='32'>";

        if ($n == 6)
            return "<img src='data:image/png;base64,' width='32' height='32'>";

        if ($n == 7)
            return "<img src='data:image/png;base64,' width='32' height='32'>";

        if ($n == 8)
            return "<img src='data:image/png;base64,' width='32' height='32'>";
    }

    public static function Show($message, $width = 400)
    {
        echo "<br>";
        echo "<div style='position: relative; text-align: left; width: " . $width . "px'>";
        echo self::RandImage();
        echo "<span style='font-family: verdana; font-size: 11px; color: #666; position: absolute; top: 5px; left: 38px;'>$message</span>";
        echo "</div>";
        echo "<br>";
    }

    public static function ShowCenter($message, $width = 400, $height = 80)
    {
        echo "<br><br>";
        echo "<div style='position: relative; width: 100%; height: " . $height . "px;'>";
        echo "<div style='position: absolute; text-align: left; top: 50%; left: 55%; transform: translate(-50%, -50%); width: " . $width . "px;'>";
        echo self::RandImage();
        echo "<span style='font-family: verdana; font-size: 11px; color: #666; position: absolute; top: 5px; left: 38px;'>$message</span>";
        echo "</div>";
        echo "</div>";
        echo "<br>";
    }

    public static function ShowLeft($message, $width = 400, $height = 80)
    {
        echo "<div style='position: relative; width: 100%; height: " . $height . "px;'>";
        echo "<div style='position: absolute; text-align: left; top: 10px; left: 10px; width: " . $width . "px;'>";
        echo self::RandImage();
        echo "<span style='font-family: verdana; font-size: 11px; color: #666; position: absolute; top: 5px; left: 38px;'>$message</span>";
        echo "</div>";
        echo "</div>";
        echo "<br>";
    }
}

